package lk.repairdesk.api.service; import lk.repairdesk.api.domain.*; import lk.repairdesk.api.dto.AuthDtos.*; import lk.repairdesk.api.repository.UserRepository; import lk.repairdesk.api.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final UserDetailsService details; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,AuthenticationManager a,UserDetailsService d,JwtService j){users=u;encoder=e;auth=a;details=d;jwt=j;} @Transactional public AuthResponse register(RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new IllegalArgumentException("Email is already registered");var u=new User();u.setName(r.name().trim());u.setEmail(r.email().trim().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(Role.CUSTOMER);users.save(u);return response(u);} public AuthResponse login(LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password()));var u=users.findByEmailIgnoreCase(r.email()).orElseThrow();return response(u);} private AuthResponse response(User u){return new AuthResponse(jwt.generate(details.loadUserByUsername(u.getEmail())),u.getId(),u.getName(),u.getEmail(),u.getRole());} }